package io.quarkus.runtime.configuration;

import io.smallrye.config.Config;

/**
 * Resolves {@code @ConfigRoot} configuration mappings from the current SmallRye configuration.
 * <p>
 * This class is the runtime target of bytecode generated by the ServiceRegistrar lambda
 * transliteration system. Two kinds of generated code call it:
 * <ul>
 * <li>the deploy body of a service action whose {@code require(...)} dependency is a
 * {@code @ConfigRoot} mapping (a config-direct dependency), and</li>
 * <li>the capture reconstruction code emitted when a service action lambda captured a
 * {@code @ConfigRoot} mapping instance.</li>
 * </ul>
 * In both cases the mapping interface and its prefix are known at build time and are
 * emitted as constants, so no prefix discovery happens at runtime.
 */
public final class ConfigLookup {

    private ConfigLookup() {
    }

    /**
     * Resolve a {@code @ConfigMapping} interface registered under the given prefix
     * from the current SmallRye configuration.
     *
     * @param type the configuration mapping interface class to resolve
     * @param prefix the prefix the mapping was registered with
     * @param <T> the configuration mapping type
     * @return the resolved configuration mapping instance
     */
    public static <T> T getConfigMapping(Class<T> type, String prefix) {
        return Config.get().getConfigMapping(type, prefix);
    }
}
